413→export default function SizeCharts() {
414→  const { charts, plan, templates, categories, canCreate } =
415→    useLoaderData<typeof loader>();
416→  const fetcher = useFetcher<typeof action>();
417→  const shopify = useAppBridge();
418→  const navigate = useNavigate();
419→
420→  const [showTemplates, setShowTemplates] = useState(false);
421→  const [showImport, setShowImport] = useState(false);
422→  const [importName, setImportName] = useState("Imported Size Chart");
423→  const [importCategory, setImportCategory] = useState("general");
424→  const [importCsvText, setImportCsvText] = useState("");
425→  const [statusFilter, setStatusFilter] = useState<"all" | "active" | "draft">("all");
426→  const [categoryFilter, setCategoryFilter] = useState("all");
427→  const [searchQuery, setSearchQuery] = useState("");
428→
429→  const isLoading = fetcher.state !== "idle";
430→
431→  useEffect(() => {
432→    if (!fetcher.data) return;
433→    const data = fetcher.data as ActionData;
434→    if ("ok" in data && data.ok) {
435→      shopify.toast.show(data.message);
436→      if ("redirectId" in data && data.redirectId) {
437→        window.location.href = `/app/size-charts/${data.redirectId}`;
438→      } else {
439→        setShowTemplates(false);
440→        setShowImport(false);
441→        setImportCsvText("");
442→        setImportName("Imported Size Chart");
443→      }
444→    } else if ("error" in data) {
445→      shopify.toast.show(data.error, { isError: true });
446→    }
447→  }, [fetcher.data, shopify]);
448→
449→  const filteredCharts = charts.filter((chart) => {
450→    const matchesStatus = statusFilter === "all" || chart.status === statusFilter;
451→    const matchesCategory = categoryFilter === "all" || chart.category === categoryFilter;
452→    const matchesSearch =
453→      searchQuery.trim() === "" ||
454→      chart.name.toLowerCase().includes(searchQuery.toLowerCase());
455→    return matchesStatus && matchesCategory && matchesSearch;
456→  });
457→
458→  const publishedCount = charts.filter((c) => c.status === "active").length;
459→  const activeFilteredCount = charts.filter((c) => c.status === "active").length;
460→  const draftFilteredCount = charts.filter((c) => c.status === "draft").length;
461→  const maxCharts = plan.limits.maxCharts;
462→  const isFreePlan = plan.id === "free";
463→
464→  const progressPct =
465→    maxCharts > 0 ? Math.min(100, Math.round((publishedCount / maxCharts) * 100)) : 0;
466→  const progressColor =
467→    publishedCount >= maxCharts && maxCharts > 0 ? "#d72c0d" : "#1a73e8";
468→
469→  const categoryFilterOptions = [
470→    { label: "All categories", value: "all" },
471→    ...categories.map((cat) => ({ label: CATEGORY_LABELS[cat] ?? cat, value: cat })),
472→  ];
473→
474→  function clearFilters() {
475→    setStatusFilter("all");
476→    setCategoryFilter("all");
477→    setSearchQuery("");
478→  }
479→
480→  return (
481→    <Page
482→      title="Size Charts"
483→      backAction={{ onAction: () => navigate("/app") }}
484→      primaryAction={
485→        <Button
486→          variant="primary"
487→          onClick={() => setShowTemplates(!showTemplates)}
488→          disabled={!canCreate || isLoading}
489→        >
490→          {canCreate
491→            ? showTemplates
492→              ? "Cancel"
493→              : "Create chart"
494→            : `Limit reached (${plan.limits.maxCharts})`}
495→        </Button>
496→      }
497→      secondaryActions={[
498→        {
499→          content: "Import CSV",
500→          onAction: () => {
501→            setShowImport(!showImport);
502→            setShowTemplates(false);
503→          },
504→        },
505→      ]}
506→    >
507→      <Layout>
508→
509→        {/* ================================================================ */}
510→        {/* PLAN LIMIT BANNER                                                 */}
511→        {/* ================================================================ */}
512→        {!canCreate && (
513→          <Layout.Section>
514→            <Banner tone="warning" title="Chart limit reached">
515→              <BlockStack gap="200">
516→                <Text as="p" variant="bodyMd">
517→                  You have reached the {plan.limits.maxCharts}-chart limit on the{" "}
518→                  {plan.name} plan. Upgrade to Starter for unlimited charts with no
519→                  hidden fees.
520→                </Text>
521→                <Button variant="primary" url="/app/pricing">Upgrade plan</Button>
522→              </BlockStack>
523→            </Banner>
524→          </Layout.Section>
525→        )}
526→
527→        {/* ================================================================ */}
528→        {/* TEMPLATE PICKER MODAL                                             */}
529→        {/* ================================================================ */}
530→        <Modal
531→          open={showTemplates}
532→          onClose={() => setShowTemplates(false)}
533→          title="Create a size chart"
534→        >
535→          <Modal.Section>
536→            <BlockStack gap="200">
537→              <Text as="p" variant="bodyMd" tone="subdued">
538→                Start from scratch or choose a pre-filled template
539→              </Text>
540→            </BlockStack>
541→          </Modal.Section>
542→          <Modal.Section>
543→            <TemplatePicker
544→              templates={templates}
545→              categories={categories}
546→              isLoading={isLoading}
547→              onClose={() => setShowTemplates(false)}
548→              fetcher={fetcher}
549→            />
550→          </Modal.Section>
551→        </Modal>
552→
553→        {/* ================================================================ */}
554→        {/* CSV IMPORT MODAL                                                  */}
555→        {/* ================================================================ */}
556→        <Modal
557→          open={showImport}
558→          onClose={() => setShowImport(false)}
559→          title="Import Size Chart from CSV"
560→          primaryAction={{
561→            content: "Import chart",
562→            onAction: () => {
563→              const formData = new FormData();
564→              formData.set("intent", "import-csv");
565→              formData.set("name", importName);
566→              formData.set("category", importCategory);
567→              formData.set("csvData", importCsvText);
568→              fetcher.submit(formData, { method: "post" });
569→            },
570→            loading: isLoading,
571→            disabled: !importCsvText.trim(),
572→          }}
573→          secondaryActions={[
574→            { content: "Cancel", onAction: () => setShowImport(false) },
575→          ]}
576→        >
577→          <Modal.Section>
578→            <BlockStack gap="400">
579→              <Text as="p" variant="bodyMd" tone="subdued">
580→                Paste your CSV data below. The first row must be column headers (e.g. Size, Chest, Waist).
581→              </Text>
582→
583→              <Banner tone="info">
584→                <Text as="p" variant="bodySm">
585→                  {`Expected format: Size,Chest,Waist,Hips — one row per size (XS, S, M, L, XL, etc.)`}
586→                </Text>
587→              </Banner>
588→
589→              <InlineStack gap="400" align="start" wrap={false}>
590→                <div style={{ flex: 2, minWidth: "180px" }}>
591→                  <TextField
592→                    label="Chart name"
593→                    value={importName}
594→                    onChange={setImportName}
595→                    placeholder="e.g. Women's Tops"
596→                    autoComplete="off"
597→                  />
598→                </div>
599→                <div style={{ flex: 1, minWidth: "140px" }}>
600→                  <Select
601→                    label="Category"
602→                    options={CATEGORY_SELECT_OPTIONS}
603→                    value={importCategory}
604→                    onChange={setImportCategory}
605→                  />
606→                </div>
607→              </InlineStack>
608→
609→              <TextField
610→                label="CSV data"
611→                value={importCsvText}
612→                onChange={setImportCsvText}
613→                multiline={8}
614→                placeholder={"Size,Chest,Waist,Hips\nXS,32-34,24-26,34-36\nS,34-36,26-28,36-38"}
615→                autoComplete="off"
616→              />
617→
618→              <Text as="p" variant="bodySm" tone="subdued">
619→                Chart will be created as a draft — review and publish when ready.
620→              </Text>
621→            </BlockStack>
622→          </Modal.Section>
623→        </Modal>
624→
625→        {/* ================================================================ */}
626→        {/* CHARTS LIST (with integrated search/filters)                     */}
627→        {/* ================================================================ */}
628→        <Layout.Section>
629→          <Card>
630→            <BlockStack gap="400">
631→
632→              {/* Header + count */}
633→              {charts.length > 0 && (
